class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int minPrice = INT_MAX, best = 0;
        for (int i = 0; i < (int)prices.size(); i++) {
            minPrice = min(minPrice, prices[i]);
            best = max(best, prices[i] - minPrice);
        }
        return best;
    }
};
